    private Query query(Query q){try{if(q==null||q.page()<0||q.size()!=20||q.kind()!=null&&!Set.of("SENDER","RECIPIENT").contains(q.kind())||q.state()!=null&&!Set.of("ACTIVE","ARCHIVED").contains(q.state()))throw new IllegalArgumentException();return new Query(q.page(),20,q.search()==null?null:OrganizationContactInput.text(q.search(),160),q.kind(),q.state()==null?"ACTIVE":q.state(),q.facilityId(),q.group()==null?null:OrganizationContactInput.text(q.group(),80));}catch(RuntimeException bad){throw fail("VALIDATION_FAILED");}}
